(()=>{
if (window.__kordranPort) return;
window.__kordranPort = true;
/* ---------- settings ---------- */
const COLOR=0.55;     // colour tint strength: 0 = pure gray, 0.3 = faint, 0.55 = soft
const DARKEST=72;     // darkest gray (0 = black, 255 = white); 72 is about 70% ink
const LIGHTEST=226;   // lightest gray used for the faintest characters
const FPS=30;
/* ------------------------------ */
const SRC="data:image/jpeg;base64,", TINT="data:image/jpeg;base64,";
const root=document.getElementById('port-ascii');
const S={
 water:(u,v)=>{const box=(a,b,c,d)=>u>a&&u<b&&v>c&&v<d;
  if(box(0.40,0.555,0.415,0.60)||box(0.345,0.41,0.545,0.625)||box(0.503,0.54,0.53,0.595)||box(0.595,0.665,0.31,0.455)||box(0.395,0.425,0.42,0.465))return 0;
  if(v<0.34||v>0.79)return 0;
  const lb=v<0.42?0.40+(0.42-v)*2:v<0.55?0.39:v<0.62?0.30:0.16,rb=v<0.55?0.605:v<0.66?0.69:0.59;
  return u>lb&&u<rb?1:0},
 rip:{amp:0.8,f:80,s:1.5},sky:0.3,
 lights:[{u:0.84,v:0.15,r:0.07,a:0.18}],
 plumes:[{u:0.915,v:0.36,su:0.03,sv:0.16},{u:0.87,v:0.6,su:0.03,sv:0.06},{u:0.975,v:0.58,su:0.025,sv:0.04}],
 movers:[{a:[0.0,0.462],b:[0.37,0.338],n:5,sp:0.045,r:0.007,amp:-0.45},{a:[0.37,0.33],b:[0.0,0.452],n:4,sp:0.035,r:0.007,amp:-0.45}]
};
const EDGE="-\\|/",LV=64,AR=16/9;
const BAYER=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5].map(v=>(v+.5)/16);
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const narrow=matchMedia('(max-width: 767px)');
const cv=document.createElement('canvas'),ctx=cv.getContext('2d',{alpha:false});root.appendChild(cv);
const buf=document.createElement('canvas'),gx=buf.getContext('2d',{alpha:false});
let CH=[],N=0,LO=new Uint8Array(256),HI=new Uint8Array(256);
let dpr=1,vw=0,vh=0,cw=0,ch=0,cols=0,rows=0,imgW=0,imgH=0,imgY=0,srcC=0,srcR=0,fs=4;
let atlas=null,lumA,toA,edA,rnd,prevG,full=true,eo=0,to=0;
let t=0,last=0,theta=-Math.PI/2,pan=0.5,glitch=null,nextGlitch=5,dirty=true,visible=true;
function gray(x){return Math.round(LIGHTEST-(LIGHTEST-DARKEST)*x)}
function hash(a,b,c){let h=(Math.imul(a,374761393)+Math.imul(b,668265263)+Math.imul(c,1442695041))|0;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}

function buildGlyphs(font){
 const all=[];for(let c=33;c<127;c++)if(c!==92)all.push(String.fromCharCode(c));
 const m=document.createElement('canvas');m.width=all.length*cw;m.height=ch;const g=m.getContext('2d',{willReadFrequently:true});
 g.font=font;g.textAlign='center';g.textBaseline='middle';g.fillStyle='#000';
 all.forEach((x,k)=>g.fillText(x,k*cw+cw/2,ch/2+ch*0.04));
 const d=g.getImageData(0,0,m.width,ch).data,cov=all.map((_,k)=>{let s=0;for(let y=0;y<ch;y++)for(let x=k*cw;x<(k+1)*cw;x++)s+=d[(y*m.width+x)*4+3];return s});
 const mx=Math.max(...cov),list=all.map((c,k)=>({c,v:cov[k]/mx})).filter(o=>o.v>0.02).sort((a,b)=>a.v-b.v);
 CH=[{c:' ',v:0},...list];N=CH.length;
 for(let b=0;b<256;b++){const tt=b/255;let best=0,bd=9;CH.forEach((o,j)=>{const dd=Math.abs(o.v-tt);if(dd<bd){bd=dd;best=j}});
  const tol=bd+0.018;let lo=best,hi=best;while(lo>1&&Math.abs(CH[lo-1].v-tt)<=tol)lo--;while(hi<N-1&&Math.abs(CH[hi+1].v-tt)<=tol)hi++;
  if(best===0){lo=hi=0}LO[b]=lo;HI[b]=hi}
}
function buildAtlas(){
 const font=`700 ${Math.round(ch*0.9)}px ui-monospace,Menlo,Consolas,"DejaVu Sans Mono",monospace`;buildGlyphs(font);
 atlas=document.createElement('canvas');atlas.width=(N+EDGE.length)*cw;atlas.height=LV*ch;
 const a=atlas.getContext('2d');a.fillStyle='#fff';a.fillRect(0,0,atlas.width,atlas.height);a.textAlign='center';a.textBaseline='middle';a.font=font;
 const G=CH.map(o=>o.c).join('')+EDGE;
 for(let l=0;l<LV;l++){const v=gray((l+.5)/LV);a.fillStyle=`rgb(${v},${v},${v})`;
  for(let k=1;k<G.length;k++)a.fillText(G[k],k*cw+cw/2,l*ch+ch/2+ch*0.04)}
}
function buildLum(){
 const o=document.createElement('canvas');o.width=srcC;o.height=srcR;const g=o.getContext('2d',{willReadFrequently:true});
 g.imageSmoothingQuality='high';g.drawImage(S.img,0,0,srcC,srcR);
 const d=g.getImageData(0,0,srcC,srcR).data,n=srcC*srcR,raw=new Float32Array(n),hist=new Uint32Array(256);
 for(let i=0;i<n;i++){raw[i]=d[i*4];hist[d[i*4]]++}
 let acc=0,lo=0,hi=255;for(let i=0;i<256;i++){acc+=hist[i];if(acc<n*0.01)lo=i;if(acc<n*0.997)hi=i}
 const L=new Float32Array(n),Wm=new Float32Array(n);
 for(let y=0;y<srcR;y++)for(let x=0;x<srcC;x++){const i=y*srcC+x;let b=0,m=0;
  for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const yy=y+dy,xx=x+dx;if(yy>=0&&yy<srcR&&xx>=0&&xx<srcC){b+=raw[yy*srcC+xx];m++}}
  let v=raw[i]+0.55*(raw[i]-b/m);v=(v-lo)/(hi-lo);v=v<0?0:v>1?1:v;L[i]=Math.pow(v,0.82);
  Wm[i]=S.water((x+.5)/srcC,(y+.5)/srcR)}
 const E=new Uint8Array(n),nr=i=>(raw[i]-lo)/(hi-lo),edgeT=0.85*Math.min(1,fs/6);
 for(let y=1;y<srcR-1;y++)for(let x=1;x<srcC-1;x++){const i=y*srcC+x;
  const a=nr(i-srcC-1),b=nr(i-srcC),c=nr(i-srcC+1),dd=nr(i-1),f=nr(i+1),gg=nr(i+srcC-1),h=nr(i+srcC),j=nr(i+srcC+1);
  const gX=((c+2*f+j)-(a+2*dd+gg))/cw,gY=((gg+2*h+j)-(a+2*b+c))/ch,m=Math.hypot(gX*cw,gY*ch);
  if(m<edgeT||Wm[i]>0.05)continue;const ph=(Math.atan2(gY,gX)*180/Math.PI+90+360)%180;
  E[i]=ph<22.5||ph>=157.5?1:ph<67.5?2:ph<112.5?3:4}
 const T=new Float32Array(n),Sm=new Float32Array(n),rad=2;
 for(let y=0;y<srcR;y++){let a=0,m=0;for(let x=-rad;x<srcC;x++){if(x+rad<srcC){a+=L[y*srcC+x+rad];m++}if(x-rad-1>=0){a-=L[y*srcC+x-rad-1];m--}if(x>=0)T[y*srcC+x]=a/m}}
 for(let x=0;x<srcC;x++){let a=0,m=0;for(let y=-rad;y<srcR;y++){if(y+rad<srcR){a+=T[(y+rad)*srcC+x];m++}if(y-rad-1>=0){a-=T[(y-rad-1)*srcC+x];m--}if(y>=0)Sm[y*srcC+x]=a/m}}
 S.L=L;S.W=Wm;S.E=E;S.S=Sm;
}
function layout(){
 vw=root.clientWidth;vh=root.clientHeight;if(!vw||!vh)return;
 dpr=Math.min(devicePixelRatio||1,3);
 fs=vw<600?3:vw<1100?3.5:4;
 cv.width=Math.round(vw*dpr);cv.height=Math.round(vh*dpr);buf.width=cv.width;buf.height=cv.height;
 ch=Math.max(7,Math.round(fs*dpr));cw=Math.max(4,Math.round(ch*0.6));
 cols=Math.ceil(cv.width/cw);rows=Math.ceil(cv.height/ch);
 imgW=Math.max(vw,vh*AR)*dpr;imgH=imgW/AR;imgY=(cv.height-imgH)/2;   // cover the box, centred
 srcC=Math.round(imgW/cw);srcR=Math.round(imgH/ch);
 lumA=new Float32Array(cols*rows);toA=new Float32Array(cols*rows);edA=new Uint8Array(cols*rows);rnd=new Float32Array(cols*rows);
 for(let i=0;i<cols*rows;i++)rnd[i]=hash(i%cols,(i/cols)|0,11);
 prevG=new Int32Array(cols*rows);full=true;
 buildAtlas();if(S.img)buildLum();dirty=true;
}
function samp(L,x,y){
 if(x<0)x=0;else if(x>srcC-1.001)x=srcC-1.001;if(y<0)y=0;else if(y>srcR-1.001)y=srcR-1.001;
 const xi=x|0,yi=y|0,fx=x-xi,fy=y-yi,i=yi*srcC+xi;
 const a=L[i]+(L[i+1]-L[i])*fx,b=L[i+srcC]+(L[i+srcC+1]-L[i+srcC])*fx;return a+(b-a)*fy;
}
function cell(c,r,imgX,slot){
 const sx=(c*cw+cw/2-imgX)/cw-.5,sy=(r*ch+ch/2-imgY)/ch-.5;
 if(sx<-.5||sy<-.5||sx>srcC-.5||sy>srcR-.5)return -1;
 const u=(sx+.5)/srcC,v=(sy+.5)/srcR,k=srcC/220;
 const ix=Math.min(srcC-1,Math.max(0,Math.round(sx))),iy=Math.min(srcR-1,Math.max(0,Math.round(sy)));
 const w=S.W[iy*srcC+ix];eo=S.E[iy*srcC+ix];let x=sx,y=sy,extra=0;
 if(w>0){const R=S.rip,d=0.5+v;
  x+=w*R.amp*k*d*(Math.sin(v*R.f+t*R.s)*0.7+Math.sin(v*R.f*2.3-t*R.s*1.3+u*6)*0.3);
  y+=w*0.3*k*Math.sin(u*40+t*R.s*0.8);
  extra+=w*0.07*Math.sin(u*90+v*40-t*3)*Math.sin(v*170+t*2.1)}
 for(const q of S.plumes){const a=(u-q.u)/q.su,b=(v-q.v)/q.sv,g=Math.exp(-a*a-b*b);if(g>0.02)x+=g*k*1.4*Math.sin(v*40+t*1.3)}
 const base=samp(S.L,x,y);let L=base+extra;
 if(v<S.sky){const tq=Math.floor(t*5)/5;L+=0.07*L*Math.sin(u*9-tq*0.12+Math.sin(v*14+tq*0.05)*2)*(1-v/S.sky)}
 for(const o of S.lights){const du=(u-o.u)*AR,dv=v-o.v,d2=du*du+dv*dv;if(d2>9*o.r*o.r)continue;
  const g=Math.exp(-d2/(o.r*o.r));if(g>0.01)L+=g*o.a*(0.7+0.3*Math.sin(t*0.9))*(1-L*0.4)}
 for(const q of S.plumes){const a=(u-q.u)/q.su,b=(v-q.v)/q.sv,g=Math.exp(-a*a-b*b);
  if(g>0.02)L+=g*0.16*Math.sin(v*90+u*30+t*2.2)+g*0.08*Math.sin(v*37-u*20+t*1.1)}
 for(const m of S.movers)for(let j=0;j<m.n;j++){const f=(t*m.sp+j/m.n)%1,mu=m.a[0]+(m.b[0]-m.a[0])*f,mv=m.a[1]+(m.b[1]-m.a[1])*f;
  const du=(u-mu)*AR,dv=v-mv;if(Math.abs(du)>3*m.r||Math.abs(dv)>3*m.r)continue;const g=Math.exp(-(du*du+dv*dv)/(m.r*m.r));if(g>0.02)L+=g*m.amp}
 if(hash(c,r,slot)>0.985)L+=(hash(r,c,slot)-.5)*0.14;
 to=S.S[iy*srcC+ix]+(L-base);to=to<0?0:to>1?1:to;
 return L<0?0:L>1?1:L;
}
function draw(){
 const imgX=-(imgW-cv.width)*pan,slot=Math.floor(t*10);
 gx.fillStyle='#fff';if(full){gx.fillRect(0,0,cv.width,cv.height);prevG.fill(-1)}
 for(let r=0;r<rows;r++){const sh=glitch&&glitch.rows[r]?glitch.rows[r]:0;
  for(let c=0;c<cols;c++){const i=r*cols+c,L=cell(c+sh,r,imgX,slot);
   if(L<0){lumA[i]=-1;continue}lumA[i]=L;toA[i]=to;edA[i]=eo}}
 const GW=N+EDGE.length;
 for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const i=r*cols+c,L=lumA[i];let g=0,k=0,l=0;
  if(L>=0){let x=(0.95-L)/0.9;if(x>1)x=1;const e=edA[i];
   if(x>0||e){if(x<0)x=0;x=x*0.4+x*x*(3-2*x)*0.6;
    const b=(Math.pow(x,0.72)*255)|0;k=LO[b]+Math.floor(rnd[i]*(HI[b]-LO[b]+1));
    let y=(0.95-toA[i])/0.9;y=y<0?0:y>1?1:y;y=Math.pow(0.5*y+0.5*x,0.8);
    l=Math.floor(y*LV+BAYER[(r&3)*4+(c&3)]-0.5);l=l<0?0:l>=LV?LV-1:l;
    if(e&&x<0.8){k=N+e-1;l=Math.max(l,8)}
    if(k)g=l*GW+k+1}}
  if(g===prevG[i])continue;prevG[i]=g;
  if(g)gx.drawImage(atlas,k*cw,l*ch,cw,ch,c*cw,r*ch,cw,ch);else gx.fillRect(c*cw,r*ch,cw,ch)}
 full=false;
 ctx.globalCompositeOperation='copy';ctx.globalAlpha=1;ctx.drawImage(buf,0,0);
 if(COLOR>0&&S.tint){ctx.globalCompositeOperation='color';ctx.globalAlpha=COLOR;ctx.drawImage(S.tint,imgX,imgY,imgW,imgH)}
 ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
}
function tick(now){
 requestAnimationFrame(tick);if(now-last<1000/FPS)return;
 if(document.documentElement.hasAttribute("data-snap-glide")){last=now;return}
 const dt=Math.min(0.1,(now-last)/1000);last=now;
 if(!visible||document.hidden)return;           // pause while off screen or in a background tab
 if(!reduce){t+=dt;dirty=true;
  if(imgW>cv.width+2){theta+=dt*(narrow.matches?0.01:0.05);pan=0.5+0.5*Math.sin(theta)}else pan=0.5;
  if(t>nextGlitch){const g={rows:{},end:t+0.12+Math.random()*0.1},r0=(Math.random()*rows)|0,h=2+((Math.random()*5)|0);
   for(let r=r0;r<r0+h;r++)g.rows[r]=((Math.random()*10)|0)-5;glitch=g;nextGlitch=t+5+Math.random()*7}
  if(glitch&&t>glitch.end)glitch=null}
 if(dirty&&atlas&&S.L){draw();dirty=false}
}
let rt;const ro=new ResizeObserver(()=>{clearTimeout(rt);rt=setTimeout(layout,120)});ro.observe(root);
new IntersectionObserver(es=>{visible=es[0].isIntersecting}).observe(root);
layout();
const tint=new Image();tint.onload=()=>{S.tint=tint;dirty=true};tint.src=TINT;
const im=new Image();im.onload=()=>{S.img=im;if(srcC)buildLum();dirty=true};im.src=SRC;
requestAnimationFrame(tick);
})();
